export const I18N: Record<Locale, Record<string, string>> = {
  en: { ...en, ...LORE_EN },
  it: { ...it, ...LORE_IT },
};

export function translate(locale: Locale, key: string): string {
  return I18N[locale][key] ?? I18N.en[key] ?? key;
}
